cd /Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature; python3 - <<'PY'
import pathlib
p = pathlib.Path('src/codegen_support/runtime/resources/stream/x86_64.rs')
t = p.read_text()
OLD = '''    emitter.label("__rt_stream_close_backend_fd");
    emitter.instruction("mov rdi, r11");                                        // pass the owned descriptor to libc close
    emitter.instruction("test rdi, rdi");                                       // skip absent descriptors
    emitter.instruction("js __rt_stream_close_backend_mark");                   // an absent descriptor needs no syscall
    emitter.instruction("call close");                                          // close the native file or socket descriptor
    emitter.instruction("jmp __rt_stream_close_backend_mark");                  // finish lifecycle publication'''
NEW = '''    emitter.label("__rt_stream_close_backend_fd");
    emitter.instruction("mov rdi, r11");                                        // pass the owned descriptor to libc close
    emitter.instruction("test rdi, rdi");                                       // skip absent descriptors
    emitter.instruction("js __rt_stream_close_backend_mark");                   // an absent descriptor needs no syscall
    emitter.instruction("call close");                                          // close the native file or socket descriptor
    // See the AArch64 counterpart: `tmpfile()` owns the file its URI names, and php removes it
    // exactly here.
    emitter.instruction("mov r10, QWORD PTR [rbp - 32]");                       // the StreamState this close is destroying
    emitter.instruction("test r10, r10");
    emitter.instruction("jz __rt_stream_close_backend_mark");
    emitter.instruction(&format!(
        "mov r11, QWORD PTR [r10 + {}]", STREAM_OWNERSHIP_FLAGS_OFFSET
    ));
    emitter.instruction(&format!(
        "test r11, {}", STREAM_STATE_FLAG_UNLINK_ON_CLOSE
    ));                                                                         // does this stream own its file?
    emitter.instruction("jz __rt_stream_close_backend_mark");
    emitter.instruction(&format!(
        "mov rax, QWORD PTR [r10 + {}]", STREAM_URI_PTR_OFFSET
    ));                                                                         // the path it published
    emitter.instruction(&format!(
        "mov rdx, QWORD PTR [r10 + {}]", STREAM_URI_LEN_OFFSET
    ));
    emitter.instruction("test rax, rax");
    emitter.instruction("jz __rt_stream_close_backend_mark");                   // nothing recorded: nothing to remove
    emitter.instruction("call __rt_cstr");                                      // the path as a C string
    emitter.instruction("mov rdi, rax");
    emitter.instruction("call unlink");                                         // a missing file is not an error here
    emitter.instruction("jmp __rt_stream_close_backend_mark");                  // finish lifecycle publication'''
assert t.count(OLD) == 1
t = t.replace(OLD, NEW, 1)
OLD = '''    STREAM_URI_PTR_OFFSET,
};'''
NEW = '''    STREAM_STATE_FLAG_UNLINK_ON_CLOSE,
    STREAM_URI_PTR_OFFSET,
};'''
assert t.count(OLD) == 1
p.write_text(t.replace(OLD, NEW, 1))
print('x86 close unlinks what the stream owns')
